		defer close(messages)
		scanner := bufio.NewScanner(resp.Body)
		for scanner.Scan() {
			data, ok := strings.CutPrefix(scanner.Text(), "data: ")
			if !ok {
				continue
			}
			var message listenMessage
			if json.Unmarshal([]byte(data), &message) == nil {
				messages <- message
			}
		}
